package in.finseq.insurance;
import android.app.*;import android.os.*;import android.widget.*;import org.json.*;
public class UnassignedPoliciesActivity extends FinseqActivity{
 LinearLayout root,list;JSONArray customers=new JSONArray();public void onCreate(Bundle b){super.onCreate(b);root=Ui.column(this);Ui.appHeader(root,this,"Unassigned Policies");LinearLayout body=Ui.contentColumn(this);root.addView(body);body.addView(Ui.sub(this,"Policies uploaded without choosing a client. Link later to an existing customer."));list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);setContentView(Ui.scroll(this,root));load();}
 void load(){Ui.run(this,()->{try{JSONObject sync=ApiClient.get(this,"/api/v1/sync");customers=sync.optJSONArray("customers");if(customers==null)customers=new JSONArray();JSONObject j=ApiClient.get(this,"/api/v3/policies/unassigned");JSONArray a=j.optJSONArray("policies");Ui.ui(this,()->render(a));}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 void render(JSONArray a){list.removeAllViews();if(a==null||a.length()==0){list.addView(Ui.sub(this,"No unassigned policy is waiting for mapping."));return;}for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);LinearLayout c=Ui.card(this);c.addView(Ui.text(this,x.optString("policy_number","Unassigned Policy"),17,true));c.addView(Ui.sub(this,x.optString("insurer")+" · "+x.optString("policy_type")));c.addView(Ui.sub(this,"Detected customer: "+x.optString("customer_name","—")));c.addView(Ui.badge(this,"UNASSIGNED",Ui.AMBER));Button link=Ui.greenButton(this,"Link Existing Customer");int id=x.optInt("id");link.setOnClickListener(v->choose(id));c.addView(link);list.addView(c);}}
 void choose(int draftId){if(customers.length()==0){Ui.toast(this,"No customer available");return;}String[] n=new String[customers.length()];for(int i=0;i<n.length;i++){JSONObject c=customers.optJSONObject(i);n[i]=c.optString("name")+" · "+c.optString("mobile");}new AlertDialog.Builder(this).setTitle("Link Existing Customer").setItems(n,(d,w)->{JSONObject c=customers.optJSONObject(w);link(draftId,c.optInt("id"));}).show();}
 void link(int draftId,int customerId){Ui.run(this,()->{try{JSONObject r=ApiClient.post(this,"/api/v3/policies/unassigned/"+draftId+"/link",new JSONObject().put("customer_id",customerId));Ui.ui(this,()->{Ui.toast(this,r.optString("message","Policy linked"));load();});}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
}
